import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
let activeId: string | null = null;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row is owned only by this worker process. Any such row left on startup
// was interrupted and is made eligible for another attempt.
db.exec('BEGIN IMMEDIATE');
try {
  const now = new Date().toISOString();
  db.prepare("UPDATE jobs SET status='queued', attempts=MAX(attempts-1, 0), progress_completed=0, result_output=NULL, error=NULL, updated_at=?, available_at=0 WHERE status='running'").run(now);
  db.exec('COMMIT');
} catch (e) { db.exec('ROLLBACK'); throw e; }

function heartbeat(): void {
  db.prepare('INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?) ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at').run(Date.now());
}
function claim(): Record<string, unknown> | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND available_at <= ? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(Date.now()) as Record<string, unknown> | undefined;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const now = new Date().toISOString();
    const rowId = String(row.id);
    db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'").run(now, rowId);
    const claimed = db.prepare('SELECT * FROM jobs WHERE id=?').get(rowId) as Record<string, unknown>;
    db.exec('COMMIT'); return claimed;
  } catch (e) { db.exec('ROLLBACK'); throw e; }
}
function finishInterrupted(): void {
  if (activeId) db.prepare("UPDATE jobs SET status='queued', attempts=MAX(attempts-1, 0), progress_completed=0, result_output=NULL, error=NULL, updated_at=?, available_at=0 WHERE id=? AND status='running'").run(new Date().toISOString(), activeId);
}

console.log('worker started');
let lastBeat = 0;
while (!stopping) {
  try {
    if (activeId) { finishInterrupted(); activeId = null; }
    if (Date.now() - lastBeat >= 500) { heartbeat(); lastBeat = Date.now(); }
    const job = claim();
    if (!job) { await sleep(100); continue; }
    const id = String(job.id); activeId = id;
    const attempts = Number(job.attempts); const failAttempts = Number(job.fail_attempts); const steps = Number(job.steps);
    if (attempts <= failAttempts) {
      const terminal = attempts >= 3;
      const now = new Date().toISOString();
      if (terminal) {
        db.prepare("UPDATE jobs SET status='failed', progress_completed=0, result_output=NULL, error='transient failure', updated_at=?, available_at=0 WHERE id=? AND status='running'").run(now, id);
      } else {
        db.prepare("UPDATE jobs SET status='queued', progress_completed=0, result_output=NULL, error=NULL, updated_at=?, available_at=? WHERE id=? AND status='running'").run(now, Date.now() + 500, id);
      }
      activeId = null; continue;
    }
    let interrupted = false;
    for (let step = 1; step <= steps; step++) {
      await sleep(100);
      if (stopping) { interrupted = true; break; }
      const now = new Date().toISOString();
      db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(step, now, id);
      if (Date.now() - lastBeat >= 500) { heartbeat(); lastBeat = Date.now(); }
    }
    if (interrupted) { finishInterrupted(); activeId = null; break; }
    db.prepare("UPDATE jobs SET status='completed', progress_completed=steps, result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running'").run(String(job.input).toUpperCase(), new Date().toISOString(), id);
    activeId = null;
  } catch (err) {
    console.error('worker iteration failed:', err);
    if (activeId) {
      try { finishInterrupted(); activeId = null; }
      catch (requeueError) { console.error('could not requeue interrupted job:', requeueError); }
    }
    await sleep(500);
  }
}
db.prepare('DELETE FROM worker_heartbeat WHERE id=1').run();
db.close();
